{"implementation":"def solve(case):
    import math
    from numbers import Real

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required case field")
    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list):
        raise ValueError("segments must be a list")
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise ValueError("budget must be an integer")
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    parsed = []
    names = set()
    quota_sum = 0
    capacity_sum = 0
    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("each segment must be an object")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError("missing required segment field")
        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]
        if not isinstance(name, str):
            raise ValueError("name must be a string")
        if name in names:
            raise ValueError("segment names must be unique")
        if isinstance(importance, bool) or not isinstance(importance, Real):
            raise ValueError("importance must be numeric")
        if isinstance(importance, float) and not math.isfinite(importance):
            raise ValueError("importance must be finite")
        if isinstance(minimum, bool) or not isinstance(minimum, int):
            raise ValueError("minimum must be an integer")
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise ValueError("capacity must be an integer")
        if minimum < 0 or capacity < minimum:
            raise ValueError("invalid segment quota or capacity")
        names.add(name)
        parsed.append((name, importance, minimum, capacity))
        quota_sum += minimum
        capacity_sum += capacity

    if budget < quota_sum or budget > capacity_sum:
        raise ValueError("budget outside feasible range")

    allocations = [item[2] for item in parsed]
    remaining = budget - quota_sum
    while remaining:
        best = None
        best_priority = None
        for index, item in enumerate(parsed):
            importance = item[1]
            if allocations[index] >= item[3]:
                continue
            priority = importance / (allocations[index] + 1)
            if best is None or priority > best_priority:
                best = index
                best_priority = priority
        if best is None:
            raise ValueError("unable to satisfy budget")
        allocations[best] += 1
        remaining -= 1

    return {
        "allocations": allocations,
        "by_name": {parsed[index][0]: allocations[index] for index in range(len(parsed))},
        "total": sum(allocations)
    }
